var i=`1392-chicken-parmigiana-australian-style`;var t=`world-1392`;var n=`AU`;var s=`oceania`;var r=4;var o=57;var l={en:`Chicken Parmigiana Australian Style`,ua:`Куряча парміджана по-австралійськи`};var h={en:`Chicken Parmigiana Australian Style is a dish from Australia featuring chicken breast, all-purpose flour, chicken egg, breadcrumbs. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Куряча парміджана по-австралійськи, страва кухні країни Австралія з такими основними складниками: куряча грудка, пшеничне борошно універсальне, куряче яйце, панірувальні сухарі. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Pat dry, then coat evenly with the listed breading or flour components; press lightly to help it adhere.`,ua:`Обсушіть продукти й рівномірно запаніруйте їх у зазначених сухих складниках; злегка притисніть паніровку.`,t:[`standard-breading`],m:10,i:[[`chicken-breast`,760,`g`],[`all-purpose-flour`,100,`g`],[`chicken-egg`,2,`pcs`],[`breadcrumbs`,200,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 15 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 15 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:15,i:[[`canola-oil`,150,`ml`]]},{en:`Layer the previously prepared components evenly inside a baking dish, serving mold or plate appropriate to the recipe; smooth the surface and avoid mixing the layers.`,ua:`Рівномірно викладіть підготовлені компоненти шарами у формі для запікання, подавання чи на тарілці відповідно до страви; вирівняйте поверхню, не змішуючи шари.`,t:[`layered-assembly`],m:9,i:[[`tomato-passata`,350,`ml`],[`mozzarella`,290,`g`],[`smoked-ham`,170,`g`]]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 20 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 20 хвилин до готовності.`,t:[`baking`],m:20,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,24,`g`]]}];var u={slug:i,id:t,country:`AU`,region:s,servings:4,minutes:57,title:l,text:h,steps:d};export{n as country,u as default,t as id,o as minutes,s as region,r as servings,i as slug,d as steps,h as text,l as title};